"""Ambient session identity for PRISMtrace handlers.

A session is the unit of analysis for the whole platform. A trace answers
"what did one run do"; a session answers "what happened across this
conversation". Until this module existed, the only way to say which session
a run belonged to was to pass ``session_id`` into a handler constructor, so
an application that built one handler per agent got one session per agent
and the multi-agent run it was trying to observe was split silently, with
no warning. There is no re-key endpoint, so a wrong session cannot be
repaired after the fact.

The session now lives in a :class:`~contextvars.ContextVar` instead of on
the handler, and every handler reads it when a *run* starts rather than
when it is *constructed*. A long-lived handler therefore picks up whichever
session is open around the call:

    handler = PRISMtraceCallbackHandler(api_key=..., project_id=...)

    with prismtrace.session(f"chat-{user_id}"):
        agent_a.invoke(...)   # both runs land in the same session,
        agent_b.invoke(...)   # even though they share one handler

Precedence never changes: an explicit ``session_id`` argument wins, then
the ambient session, then the handler's own construction-time uuid. Code
that passes ``session_id`` explicitly behaves exactly as it did before.

Crossing a boundary a context does not follow
---------------------------------------------
``contextvars`` propagate into ``asyncio`` tasks but NOT into a plain
``threading.Thread`` or a process pool: a worker starts with an empty
context. Carry the value across by hand with the read/bind pair:

    session_id = prismtrace.current_session()
    queue.put((job, session_id))

    # ... in the worker ...
    job, session_id = queue.get()
    with prismtrace.session(session_id):
        run(job)

``bind_session`` is the same thing without a ``with`` block, for a worker
entrypoint that has no natural scope to wrap:

    token = prismtrace.bind_session(session_id)
    try:
        run(job)
    finally:
        prismtrace.unbind_session(token)
"""

from __future__ import annotations

import contextvars
from contextlib import contextmanager
from typing import Iterator, Optional

__all__ = [
    "session",
    "current_session",
    "bind_session",
    "unbind_session",
    "resolve_session",
]

# Default None rather than a generated id: "no ambient session" has to be
# distinguishable from "an ambient session that happens to be a uuid", or
# resolve_session could not fall back to the handler's own id.
_current_session: contextvars.ContextVar[Optional[str]] = contextvars.ContextVar(
    "prismtrace_session_id", default=None
)


def _normalize(session_id: str) -> str:
    """Reject an id that would silently behave as "no session"."""
    if session_id is None or not str(session_id).strip():
        raise ValueError(
            "session_id must be a non-empty string. Pass the id you want runs "
            "grouped under, for example the conversation or request id."
        )
    return str(session_id).strip()


def current_session() -> Optional[str]:
    """The session id in scope right now, or None if none is open.

    Read this to hand the session to a worker that a context does not reach.
    """
    return _current_session.get()


def bind_session(session_id: str) -> "contextvars.Token[Optional[str]]":
    """Open a session in the current context and return its reset token.

    Prefer :func:`session` where you have a scope to wrap. This exists for
    worker entrypoints that do not, and it must be paired with
    :func:`unbind_session` or the id leaks into whatever the thread runs next.
    """
    return _current_session.set(_normalize(session_id))


def unbind_session(token: "contextvars.Token[Optional[str]]") -> None:
    """Undo a :func:`bind_session`, restoring whatever was in scope before."""
    _current_session.reset(token)


@contextmanager
def session(session_id: str) -> Iterator[str]:
    """Group every run inside the block under ``session_id``.

    Nests: an inner block wins for its own duration and the outer session is
    restored on exit.
    """
    normalized = _normalize(session_id)
    token = _current_session.set(normalized)
    try:
        yield normalized
    finally:
        _current_session.reset(token)


def resolve_session(explicit: Optional[str], fallback: str) -> str:
    """Apply the one precedence rule every handler shares.

    Explicit argument, then the ambient session, then ``fallback`` (the
    handler's construction-time id). ``fallback`` is what keeps a handler
    used outside any session behaving exactly as it did before this module.
    """
    if explicit and str(explicit).strip():
        return str(explicit).strip()
    ambient = _current_session.get()
    if ambient:
        return ambient
    return fallback
